 if slug=='proof-cleanup':
  codes={f['path']:lean_code(f['text']) for f in files if f['path'].endswith('.lean')}
  if item==1:
   return [{'path':p,'candidates':[{'line':s[:m.start()].count('\n')+1,'token':m[0]} for m in re.finditer(r'\b(?:simp|simpa)\b(?!\s+only\b)',s)]} for p,s in sorted(codes.items())]
  if item==2:
   result=[];groups=collections.defaultdict(list)
   for p,s in sorted(codes.items()):
    declarations=list(re.finditer(r'(?m)^(?:private |protected )?(?:theorem|lemma|def|abbrev)\s+([\w.]+)',s))
    for n,m in enumerate(declarations):
     body=s[m.end():declarations[n+1].start() if n+1<len(declarations) else len(s)]
     norm=re.sub(r'\s+',' ',body).strip()
     if norm:groups[norm].append(p+':'+m[1])
   for p in sorted(codes):result.append({'path':p,'duplicateCandidates':sorted([names for names in groups.values() if len(names)>1 and any(name.startswith(p+':') for name in names)])})
   return result
  # Every declaration stays a candidate/public-or-dynamic review; never delete by count.
  result=[];combined='\n'.join(codes.values());occurrences=collections.Counter(re.findall(r'[\w.]+',combined))
  for p,s in sorted(codes.items()):
   names=re.findall(r'(?m)^(?:private |protected )?(?:theorem|lemma|def|abbrev)\s+([\w.]+)',s)
