  if any(r.get('mode') not in ['cold','warm'] or r.get('side') not in ['before','after'] or r.get('status') not in ['ok','error','timeout'] for r in rows):return {'verdict':'invalid-mode-side-status'}
  if any(r.get('status')!='ok' for r in rows):return {'verdict':'inconclusive-error-or-timeout'}
  if any(type(r.get('seconds')) not in (int,float) or not math.isfinite(r['seconds']) or r['seconds']<=0 for r in rows):return {'verdict':'invalid-measurements'}
  import json
