   result[mode]={}
   for side in ['before','after']:
    nums=sorted(r['seconds'] for r in rows if r['mode']==mode and r['side']==side)
    if len(nums)<3 or any(type(v) not in (int,float) or not math.isfinite(v) or v<=0 for v in nums):return {'verdict':'invalid-repeats'}
